"""Writes the settings' JSON Schemas and their TypeScript into `packages/chess-ui`.

`python -m langchain_chess_server.codegen <dir>` (`mise run generate:settings`). The rendering is
pure; a test fails when the committed files are stale.
"""

import json
import sys
from pathlib import Path
from typing import Any

from langchain_chess import model_arguments as rules
from langchain_chess_systemone.schema import input_schema, settings_schema
from langchain_chess_systemone.settings import DEFAULTS, LEGACY_KEYS, VERSION

HEADER = (
    "// Generated by `mise run generate:settings` from ChessContext in libs/systemone. Do not edit."
)

JSON_TYPE = (
    "export type JSONValue = string | number | boolean | null | JSONValue[] | "
    "{ [key: string]: JSONValue };"
)

SPEC_TYPE = """export type SettingSpec =
  | { type: "enum"; values: readonly string[]; nullable: boolean }
  | { type: "object"; nullable: boolean }
  | { type: "boolean"; nullable: boolean }
  | { type: "string"; minLength: number; nullable: boolean }
  | {
      type: "number";
      integer: boolean;
      minimum: number | null;
      maximum: number | null;
      exclusiveMinimum: number | null;
      nullable: boolean;
    };"""


def _literal(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False)


def _split(prop: dict[str, Any]) -> tuple[dict[str, Any], bool]:
    """The property's own schema, and whether it also admits null."""
    options = prop.get("anyOf")
    if options is None:
        return prop, False
    (inner,) = [option for option in options if option != {"type": "null"}]
    return inner, True


def _def_name(schema: dict[str, Any]) -> str | None:
    ref = schema.get("$ref")
    return ref.removeprefix("#/$defs/") if ref is not None else None


def _ts_type(prop: dict[str, Any]) -> str:
    inner, nullable = _split(prop)
    if "const" in inner:
        base = _literal(inner["const"])
    elif (name := _def_name(inner)) is not None:
        base = name
    elif inner["type"] == "object":
        base = "{ [key: string]: JSONValue }"
    else:
        base = {"boolean": "boolean", "string": "string", "integer": "number", "number": "number"}[
            inner["type"]
        ]
    return f"{base} | null" if nullable else base


def _spec(prop: dict[str, Any], defs: dict[str, Any]) -> dict[str, Any]:
    inner, nullable = _split(prop)
    if (name := _def_name(inner)) is not None:
        return {"type": "enum", "values": defs[name]["enum"], "nullable": nullable}
    kind = inner["type"]
    if kind == "object":
        return {"type": "object", "nullable": nullable}
    if kind == "boolean":
        return {"type": "boolean", "nullable": nullable}
    if kind == "string":
        return {"type": "string", "minLength": inner.get("minLength", 0), "nullable": nullable}
    return {
        "type": "number",
        "integer": kind == "integer",
        "minimum": inner.get("minimum"),
        "maximum": inner.get("maximum"),
        "exclusiveMinimum": inner.get("exclusiveMinimum"),
        "nullable": nullable,
    }


def _object(entries: dict[str, Any], indent: str = "  ") -> str:
    lines = [f"{indent}{name}: {_literal(value)}," for name, value in entries.items()]
    return "{\n" + "\n".join(lines) + "\n" + indent[:-2] + "}"


def typescript(schema: dict[str, Any]) -> str:
    """The settings as TypeScript: types, checks, defaults and descriptions."""
    defs: dict[str, Any] = schema["$defs"]
    properties: dict[str, Any] = schema["properties"]
    settings = {name: prop for name, prop in properties.items() if name != "version"}
    out = [HEADER, "", f"export const SETTINGS_VERSION = {VERSION};", ""]
    for name, definition in defs.items():
        if name == "JSONValue":
            out.append(JSON_TYPE)
        else:
            out.append(f"export type {name} = {' | '.join(map(_literal, definition['enum']))};")
    out += ["", f"/** {schema['description']} */", "export interface ChessContext {"]
    for name, prop in properties.items():
        out += [f"  /** {prop['description']} */", f"  {name}: {_ts_type(prop)};"]
    out += [
        "}",
        "",
        'export type SettingKey = Exclude<keyof ChessContext, "version">;',
        "",
        SPEC_TYPE,
        "",
        "export const SETTING_SPECS: Record<SettingKey, SettingSpec> = {",
        *(f"  {name}: {_literal(_spec(prop, defs))}," for name, prop in settings.items()),
        "};",
        "",
        "export const SETTING_DESCRIPTIONS: Record<SettingKey, string> = "
        + _object({name: prop["description"] for name, prop in settings.items()})
        + ";",
        "",
        "/** Each setting's name in the web app. */",
        "export const SETTING_LABELS: Record<SettingKey, string> = "
        + _object({name: prop["x-label"] for name, prop in settings.items()})
        + ";",
        "",
        "/** Each setting's tooltip: what it does and when to change it. */",
        "export const SETTING_HELP: Record<SettingKey, string> = "
        + _object({name: prop["x-help"] for name, prop in settings.items()})
        + ";",
        "",
        "export const DEFAULT_CONTEXT: ChessContext = "
        + _object({name: prop["default"] for name, prop in properties.items()})
        + ";",
        "",
        "/** Each version's keys and defaults, frozen. */",
        "export const VERSION_DEFAULTS: Readonly<Record<number, Readonly<Record<string, unknown>>>>"
        " = {",
        *(f"  {version}: {_object(dict(values), '    ')}," for version, values in DEFAULTS.items()),
        "};",
        "",
        "/** The keys of settings recorded before versions (version 0). */",
        f"export const LEGACY_KEYS: readonly string[] = {_literal(sorted(LEGACY_KEYS))};",
        "",
        "/** What `model_kwargs` may not set: libs/chess/langchain_chess/model_arguments.py. */",
        "export const MODEL_KWARGS_RULES = "
        + _object(
            {
                "connectionPattern": rules.CONNECTION_PATTERN.pattern,
                "connectionExempt": sorted(rules.CONNECTION_EXEMPT),
                "modelNames": sorted(rules.MODEL_NAMES),
                "agentOwned": sorted(rules.AGENT_OWNED),
                "appOwned": sorted(rules.APP_OWNED),
                "accountResources": sorted(rules.ACCOUNT_RESOURCES),
                "serverAllowed": sorted(rules.SERVER_ALLOWED),
                "effortNames": list(rules.EFFORT_NAMES),
                "maxTokensNames": list(rules.MAX_TOKENS_NAMES),
            }
        )
        + " as const;",
        "",
    ]
    return "\n".join(out)


def _json(schema: dict[str, Any]) -> str:
    return json.dumps(schema, indent=2, ensure_ascii=False) + "\n"


def files() -> dict[str, str]:
    """Every generated file's name and content."""
    return {
        "settings.ts": typescript(settings_schema()),
        "settings.schema.json": _json(settings_schema()),
        "opponent.schema.json": _json(input_schema()),
    }


def main(argv: list[str]) -> None:
    (target,) = argv
    directory = Path(target)
    directory.mkdir(parents=True, exist_ok=True)
    for name, content in files().items():
        (directory / name).write_text(content)


if __name__ == "__main__":
    main(sys.argv[1:])
